const fs=require('fs'),path=require('path'),os=require('os');
const GAP=Number(process.env.GAP||300);
const root=path.join(os.homedir(),'.claude/projects');
const files=[];
(function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(p.endsWith('.jsonl'))files.push(p);}})(root);
const mine=files.filter(f=>f.includes('approval-md'));
const fam=m=>{if(!m)return null;m=m.toLowerCase();for(const k of ['fable','mythos','opus','sonnet','haiku'])if(m.includes(k))return k;return m;};
const active={},wall={},sess={},msgs={},tok={};let first=Infinity,last=0;
const add=(o,k,v)=>o[k]=(o[k]||0)+v;
for(const f of mine){const ev=[];
 for(const line of fs.readFileSync(f,'utf8').split('\n')){let o;try{o=JSON.parse(line)}catch{continue}
  if(!o.timestamp)continue;const t=Date.parse(o.timestamp)/1000;let m=null;
  if(o.type==='assistant'&&o.message){m=fam(o.message.model);const u=o.message.usage||{};
   if(m){add(msgs,m,1);tok[m]=tok[m]||{};for(const k of ['input_tokens','output_tokens','cache_creation_input_tokens','cache_read_input_tokens'])add(tok[m],k,u[k]||0);}}
  ev.push([t,m]);}
 if(!ev.length)continue;ev.sort((a,b)=>a[0]-b[0]);first=Math.min(first,ev[0][0]);last=Math.max(last,ev.at(-1)[0]);
 const c={};for(const[,m]of ev)if(m)add(c,m,1);const ks=Object.keys(c);if(!ks.length)continue;
 const dom=ks.sort((a,b)=>c[b]-c[a])[0];add(sess,dom,1);add(wall,dom,ev.at(-1)[0]-ev[0][0]);
 let cur=dom;for(let i=0;i<ev.length-1;i++){if(ev[i][1])cur=ev[i][1];add(active,cur,Math.min(ev[i+1][0]-ev[i][0],GAP));}}
const d=t=>new Date(t*1000).toISOString().slice(0,10);
console.log(`files ${mine.length}  span ${d(first)} -> ${d(last)}  gap cap ${GAP}s`);
console.log('model     sessions   msgs  active_h  wall_h  out_Mtok  in_Mtok(all)  cache_read_Mtok');
for(const m of Object.keys(active).sort((a,b)=>active[b]-active[a])){const t=tok[m]||{};const tin=(t.input_tokens||0)+(t.cache_creation_input_tokens||0)+(t.cache_read_input_tokens||0);
 console.log(m.padEnd(10)+String(sess[m]||0).padStart(8)+String(msgs[m]||0).padStart(7)+(active[m]/3600).toFixed(1).padStart(10)+((wall[m]||0)/3600).toFixed(1).padStart(8)+((t.output_tokens||0)/1e6).toFixed(2).padStart(10)+(tin/1e6).toFixed(0).padStart(14)+((t.cache_read_input_tokens||0)/1e6).toFixed(0).padStart(17));}
const S=o=>Object.values(o).reduce((a,b)=>a+b,0);
console.log(`TOTAL active ${(S(active)/3600).toFixed(1)}h  wall ${(S(wall)/3600).toFixed(1)}h  sessions ${S(sess)}`);
EOF
